/**
 * `svg-minify` — an editor's records and the whitespace no renderer draws go,
 * and nothing else does. Synthetic drawings: this layer names no real IG.
 */
import { describe, expect, test } from "bun:test";
import { minifySvg, minifySvgBytes } from "./svg-minify.ts";

/** A drawing as Visio and Inkscape save one: editor namespaces, comments, indentation. */
const SAVED = `<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<!-- Generated by Microsoft Visio, SVG Export flow.svg Page-1 -->
<svg
   width="2in" height="1in"
   viewBox="0 0 144 72"
   xml:space="preserve"
   sodipodi:docname="flow.svg"
   xmlns:inkscape="http://www.inkscape.org/namespaces/inkscape"
   xmlns:sodipodi="http://sodipodi.sourceforge.net/DTD/sodipodi-0.dtd"
   xmlns="http://www.w3.org/2000/svg"
   xmlns:xlink="http://www.w3.org/1999/xlink"
   xmlns:v="http://schemas.microsoft.com/visio/2003/SVGExtensions/"><sodipodi:namedview
   id="namedview2"
   pagecolor="#ffffff"
   inkscape:document-units="in" />
\t<v:documentProperties v:langID="1033">
\t\t<v:userDefs>
\t\t\t<v:ud v:nameU="msvNoAutoConnect" v:val="VT0(0):26" />
\t\t</v:userDefs>
\t</v:documentProperties>
\t<style type="text/css">
\t<![CDATA[
\t\t.st1 {fill:#ffffff;stroke:#000000}
\t]]>
\t</style>
\t<g v:mID="0" v:index="1" inkscape:label="Page-1">
\t\t<title>Page-1</title>
\t\t<!-- Copyright 2026 Example Org. Licensed CC-BY-4.0 -->
\t\t<rect x="1.5" y="2.25"
\t\t   width="60" height="40.5" class="st1" v:layerMember="0" />
\t\t<text x="10" y="20" v:langID="1033"><v:paragraph v:horizAlign="1"/><v:tabList/>Give  vaccine<v:newlineChar/><tspan
   x="10" dy="1.2em">to  client</tspan> </text>
\t</g>
</svg>
`;

const MIN = minifySvg(SAVED);

describe("minifySvg", () => {
  test("editorRecordsDropped", () => {
    for (const gone of ["sodipodi", "inkscape", "v:", "xmlns:v=", "documentProperties", "namedview", "Generated by Microsoft Visio"]) expect(MIN).not.toContain(gone);
  });
  test("drawingKeptByteForByte", () => {
    // The root keeps every attribute a renderer reads, and the namespaces it still uses.
    expect(MIN).toStartWith('<?xml version="1.0" encoding="UTF-8" standalone="no"?><svg width="2in" height="1in" viewBox="0 0 144 72" xml:space="preserve" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">');
    expect(MIN).toContain('<rect x="1.5" y="2.25" width="60" height="40.5" class="st1"/>');
    // Text and style content is copied through: two spaces stay two, the trailing space stays.
    expect(MIN).toContain('<text x="10" y="20">Give  vaccine<tspan x="10" dy="1.2em">to  client</tspan> </text>');
    expect(MIN).toContain("<style type=\"text/css\">\n\t<![CDATA[\n\t\t.st1 {fill:#ffffff;stroke:#000000}\n\t]]>\n\t</style>");
    expect(MIN).toContain("<title>Page-1</title>");
    expect(MIN).toContain("<!-- Copyright 2026 Example Org. Licensed CC-BY-4.0 -->");
    expect(MIN).toEndWith("</g></svg>");
  });
  test("idempotent", () => {
    expect(minifySvg(MIN)).toBe(MIN);
    expect(MIN.length).toBeLessThan(SAVED.length / 2);
  });
  test("unreadableLeftAlone", () => {
    for (const odd of [
      '<!DOCTYPE svg [<!ENTITY a "b">]><svg xmlns="http://www.w3.org/2000/svg">&a;</svg>',
      '<svg xmlns="http://www.w3.org/2000/svg"><!-- open',
      '<svg xmlns="http://www.w3.org/2000/svg"><g></svg>',
      '<svg xmlns="http://www.w3.org/2000/svg" hidden>  <g/></svg>',
      '<svg xmlns:v="http://schemas.microsoft.com/visio/2003/SVGExtensions/"><g xmlns:v="http://example.org/mine"> <v:x/></g></svg>',
    ])
      expect(minifySvg(odd)).toBe(odd);
  });
  test("prefixMatchedByNamespace", () => {
    // `v:` bound to a namespace no editor owns is kept; an editor's namespace under any prefix goes.
    expect(minifySvg('<svg xmlns="http://www.w3.org/2000/svg" xmlns:v="http://example.org/mine"> <v:x v:a="1"/></svg>')).toBe('<svg xmlns="http://www.w3.org/2000/svg" xmlns:v="http://example.org/mine"><v:x v:a="1"/></svg>');
    expect(minifySvg('<svg xmlns="http://www.w3.org/2000/svg" xmlns:ink="http://www.inkscape.org/namespaces/inkscape" ink:version="1.2"> <ink:x/></svg>')).toBe('<svg xmlns="http://www.w3.org/2000/svg"></svg>');
  });
});

describe("minifySvgBytes", () => {
  test("notUtf8LeftAlone", () => {
    const latin1 = new Uint8Array([...new TextEncoder().encode('<svg xmlns="http://www.w3.org/2000/svg">  <text>caf'), 0xe9, ...new TextEncoder().encode("</text></svg>")]);
    expect(minifySvgBytes(latin1)).toBe(latin1);
    const declared = new TextEncoder().encode('<?xml version="1.0" encoding="ISO-8859-1"?>\n<svg xmlns="http://www.w3.org/2000/svg">  <g/></svg>');
    expect(minifySvgBytes(declared)).toBe(declared);
    expect(new TextDecoder().decode(minifySvgBytes(new TextEncoder().encode(SAVED)))).toBe(MIN);
  });
});
